const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};
const secret = String($env.N8N_WEBHOOK_SECRET || '').trim();
if (!secret) { throw new Error('Webhook secret not configured'); }
const header = String(headers['x-webhook-secret'] || '').trim();
if (header !== secret) { throw new Error('Invalid webhook secret'); }
return [{ json: { phone: body.phone, guestName: body.guestName, bookingCode: body.bookingCode, messageId: body.messageId, templateKey: body.templateKey || 'checkin-reminder' } }];
